let currentLocale = 'en';
function applyLocale(locale) {
 currentLocale = translations[locale] ? locale : 'en';
 const copy = translations[currentLocale];
 document.documentElement.lang = currentLocale;
 document.querySelectorAll('[data-i18n]').forEach(el => {const value=copy[el.dataset.i18n];if(value!==undefined)el.innerHTML=value;});
 document.querySelectorAll('[data-i18n-aria]').forEach(el => el.setAttribute('aria-label',copy[el.dataset.i18nAria]));
 document.querySelectorAll('[data-i18n-alt]').forEach(el => el.alt=copy[el.dataset.i18nAlt]);
 const policy = document.body.dataset.page === 'privacy';
 document.title = copy[policy ? 'policyPageTitle' : 'pageTitle'];
 document.querySelector('meta[name="description"]').content = copy[policy ? 'policyMeta' : 'meta'];
 document.getElementById('language-select').value=currentLocale;
 const pageUrl=new URL(location.href);pageUrl.searchParams.set('lang',currentLocale);
 history.replaceState(null,'',pageUrl.pathname+pageUrl.search+pageUrl.hash);
 document.querySelectorAll('.locale-link').forEach(link => {const url=new URL(link.href);url.searchParams.set('lang',currentLocale);link.href=url.pathname+url.search+url.hash;});
 try {localStorage.setItem('ozuk-locale',currentLocale);} catch {}
 document.dispatchEvent(new CustomEvent('ozuk:localechange'));
}
window.ozukLocale={t:key=>translations[currentLocale][key],apply:applyLocale};
let initialLocale = new URLSearchParams(location.search).get('lang');
if (!translations[initialLocale]) {try {initialLocale=localStorage.getItem('ozuk-locale');} catch {}}
applyLocale(initialLocale);
document.getElementById('language-select').addEventListener('change',event=>applyLocale(event.target.value));
